<?php
require_once __DIR__.'/../../includes/staff/feature-tools.php';require_permission('dashboard.view');$pdo=staff_db();$pageTitle='Business Dashboard';require __DIR__.'/../../includes/staff/header.php';
function scalar(PDO $p,string $q){try{return $p->query($q)->fetchColumn()?:0;}catch(Throwable $e){return 0;}}
$k=['Open leads'=>scalar($pdo,"SELECT COUNT(*) FROM leads WHERE stage NOT IN ('won','lost')"),'Active projects'=>scalar($pdo,"SELECT COUNT(*) FROM projects WHERE status NOT IN ('completed','cancelled')"),'Pipeline value'=>scalar($pdo,"SELECT COALESCE(SUM(estimated_value),0) FROM leads WHERE stage NOT IN ('won','lost')"),'Outstanding invoices'=>scalar($pdo,"SELECT COALESCE(SUM(balance_amount),0) FROM invoices WHERE status NOT IN ('paid','void')"),'Production jobs'=>scalar($pdo,"SELECT COUNT(*) FROM production_jobs WHERE status NOT IN ('completed')"),'Installations next 7 days'=>scalar($pdo,"SELECT COUNT(*) FROM installations WHERE scheduled_start BETWEEN NOW() AND DATE_ADD(NOW(),INTERVAL 7 DAY) AND status NOT IN ('completed','cancelled')")];$recent=db_rows($pdo,'SELECT p.project_code,p.name,p.status,p.target_date,c.name customer_name FROM projects p JOIN customers c ON c.id=p.customer_id ORDER BY p.updated_at DESC LIMIT 12');module_head('Management','Business Dashboard','A live operating snapshot across sales, projects, finance and delivery.');?><div class="module-grid"><?php foreach($k as $n=>$v):?><div class="metric-card"><small><?=h($n)?></small><strong><?=str_contains($n,'value')||str_contains($n,'invoice')?'RM '.number_format($v,2):number_format($v)?></strong></div><?php endforeach?></div><section class="staff-panel table-panel"><h2>Recently updated projects</h2><table><thead><tr><th>Project</th><th>Customer</th><th>Status</th><th>Target</th></tr></thead><tbody><?php foreach($recent as $r):?><tr><td><b><?=h($r['project_code'].' · '.$r['name'])?></b></td><td><?=h($r['customer_name'])?></td><td><span class="pill"><?=h($r['status'])?></span></td><td><?=h($r['target_date']?:'—')?></td></tr><?php endforeach?></tbody></table></section><?php module_end();require __DIR__.'/../../includes/staff/footer.php';?>